\section{Introduction}

\subsection{Setting}
Let $\iota$ be a finite index set, $N=|\iota|$, and let $\cube=\{0,1\}^{\iota}$ be
the set of Boolean configurations $\eta$, with $\eta_v=1$ read as ``site $v$ is
open''. Fix a density $p\in[0,1]$ and write $q=1-p$. The $p$-biased product measure
assigns weight
\[
  w_p(\eta)=\prod_{v\in\iota}\bigl(p\ \text{if}\ \eta_v=1,\ q\ \text{if}\ \eta_v=0\bigr),
\]
so $\PP_p(A)=\sum_{\eta\in A}w_p(\eta)$ and $\E_p[f]=\sum_{\eta}w_p(\eta)f(\eta)$.

An event $A\subseteq\cube$ is \emph{increasing} if $\eta\le\eta'$ pointwise and
$\eta\in A$ imply $\eta'\in A$. Writing $\eta^{v\to b}$ for $\eta$ with coordinate
$v$ reset to $b$, the \emph{pivotal set} at $v$ is
\[
  \Piv_v(A)=\{\eta:\ \eta^{v\to1}\in A\ \text{and}\ \eta^{v\to0}\notin A\},
\]
and the \emph{influence} of $v$ is $I_v=\PP_p(\Piv_v(A))$.

Two inequalities dominate the subject. With $P=\PP_p(A)$:
\begin{align}
  P(1-P) &\ \le\ pq\sum_v I_v, \tag{P}\label{eq:poincare}\\
  pq\sum_v I_v^2 &\ \le\ P(1-P). \tag{L2}\label{eq:l2}
\end{align}
Inequality \eqref{eq:poincare} is the discrete Poincar\'e (Efron--Stein) inequality
specialized to a monotone event; combined with the Margulis--Russo formula
$\frac{d}{dp}\PP_p(A)=\sum_vI_v$ it drives sharp-threshold arguments. Inequality
\eqref{eq:l2} is Bessel's inequality for the degree-$\le1$ family
$\{1\}\cup\{\psi_v\}$ and yields, by Cauchy--Schwarz, the \emph{square-root law}
$pq(\sum_vI_v)^2\le N\,P(1-P)$, in particular $\sum_vI_v\le\sqrt{N}$ at $p=1/2$.

Both are inequalities, and in both cases the loss has the same source: the family of
characters used is incomplete. This paper completes it and computes both defects
exactly.

\subsection{Contributions}
\begin{enumerate}
  \item The product rule (Theorem~\ref{thm:product}), the only place where
        independence is used.
  \item Full orthogonality of the higher characters (Theorem~\ref{thm:orth}).
  \item The reproducing-kernel identity (Theorem~\ref{thm:kernel}) and completeness
        (Theorem~\ref{thm:complete}).
  \item Parseval and the variance form (Theorems~\ref{thm:parseval},
        \ref{thm:variance}); Plancherel for Boolean functions
        (Theorem~\ref{thm:plancherel}).
  \item The exact energy decomposition for increasing events
        (Theorem~\ref{thm:energy}) with the equality case and strict-improvement
        statements for \eqref{eq:l2}.
  \item The site-energy identity (Theorem~\ref{thm:siteenergy}), the exact
        Efron--Stein defect (Theorem~\ref{thm:defect}), and the characterization of
        equality in \eqref{eq:poincare} (Theorem~\ref{thm:poineq}).
  \item Algorithms, including a division-free $O(N2^N)$ biased fast transform, and
        exact rational numerical verification.
\end{enumerate}

\section{Notation and basic objects}

\begin{definition}[Weight and expectation]
$w_p(\eta)=\prod_v(p\ \text{if}\ \eta_v=1\ \text{else}\ q)$;
$\E_p[f]=\sum_\eta w_p(\eta)f(\eta)$; $\PP_p(A)=\E_p[\ind_A]$.
\end{definition}
Since $\sum_\eta w_p(\eta)=1$, the functional $\E_p$ is linear, monotone and
normalized.

\begin{definition}[$\pm1$ indicator]
For an event $A$ put $g_A(\eta)=+1$ if $\eta\in A$ and $-1$ otherwise. Then
$g_A^2\equiv1$, $\E_p[g_A]=2P-1$ and $\Var_p(g_A)=4P(1-P)$.
\end{definition}

\begin{definition}[Single-site character]
For $v\in\iota$,
\[
  \psi_v(\eta)=\begin{cases}q,&\eta_v=1,\\ -p,&\eta_v=0,\end{cases}
  \qquad\text{equivalently}\quad \psi_v(\eta)=\eta_v-p .
\]
\end{definition}
Direct computation gives $\E_p[\psi_v]=pq+q(-p)=0$ and
$\E_p[\psi_v^2]=pq^2+qp^2=pq$. We use the unnormalized character throughout; the
factors $(pq)^{|S|}$ below are the price of that choice.

\begin{definition}[Discrete derivative and average]
For $v\in\iota$,
\[
  D_vf(\eta)=f(\eta^{v\to1})-f(\eta^{v\to0}),\qquad
  A_vf(\eta)=p\,f(\eta^{v\to1})+q\,f(\eta^{v\to0}).
\]
A function $h$ is \emph{$v$-independent} if $h(\eta^{v\to b})=h(\eta)$ for all
$\eta,b$; both $D_vf$ and $A_vf$ are $v$-independent.
\end{definition}

\section{The engine: the product rule}

\begin{theorem}[Product rule]\label{thm:product}
For every family $(g_v)_{v\in\iota}$ of functions $\{0,1\}\to\R$,
\[
  \E_p\Bigl[\prod_{v\in\iota}g_v(\eta_v)\Bigr]
  \;=\;\prod_{v\in\iota}\bigl(p\,g_v(1)+q\,g_v(0)\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand the right-hand side by the distributive law: a product of $N$ two-term sums is
the sum, over all choice functions $\eta:\iota\to\{0,1\}$, of
$\prod_v[(p\ \text{if}\ \eta_v=1\ \text{else}\ q)\,g_v(\eta_v)]$. Splitting each
factor and recognizing $w_p(\eta)=\prod_v(p\ \text{if}\ \eta_v=1\ \text{else}\ q)$
turns this into $\sum_\eta w_p(\eta)\prod_vg_v(\eta_v)$, the left-hand side.
\end{proof}

This single statement is the entire content of ``the coordinates are independent''
in the form needed below.

\section{Higher characters and full orthogonality}

\begin{definition}[Biased Walsh characters]
For $S\subseteq\iota$ set $\psi_S(\eta)=\prod_{v\in S}\psi_v(\eta)$, with
$\psi_\emptyset\equiv1$. We call $|S|$ the \emph{degree}.
\end{definition}

\begin{lemma}[Full-support form]\label{lem:fullsupport}
$\psi_S(\eta)=\prod_{v\in\iota}c_v(\eta_v)$ where $c_v=\psi_v$ for $v\in S$ and
$c_v\equiv1$ otherwise.
\end{lemma}
This reformulation presents $\psi_S$, and any product $\psi_S\psi_T$, as a product
over \emph{all} coordinates of one-coordinate functions, so that
Theorem~\ref{thm:product} applies.

\begin{theorem}[Orthogonality]\label{thm:orth}
For all $S,T\subseteq\iota$,
\[
  \E_p[\psi_S\,\psi_T]=\begin{cases}(pq)^{|S|},& S=T,\\ 0,& S\neq T.\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:fullsupport}, $\psi_S\psi_T=\prod_vh_v(\eta_v)$ where
$h_v=\psi_v^2$ on $S\cap T$, $h_v=\psi_v$ on the symmetric difference
$S\,\triangle\,T$, and $h_v\equiv1$ elsewhere. Theorem~\ref{thm:product} turns the
expectation into a product of local factors: $pq$ on $S\cap T$, $0$ on
$S\,\triangle\,T$, and $1$ elsewhere. A single site in the symmetric difference
annihilates the product; if $S=T$ every one of the $|S|$ factors contributes $pq$.
\end{proof}

Thus $\{\psi_S\}_{S\subseteq\iota}$ is an orthogonal system of $2^N$ vectors in the
$2^N$-dimensional space $\R^{\cube}$ with the inner product
$\langle f,g\rangle_p=\E_p[fg]$, nondegenerate whenever $0<p<1$.

\section{The reproducing kernel and completeness}

\begin{definition}[Fourier coefficient and level energy]
For $0<p<1$,
\[
  \hat f(S)=\frac{\E_p[f\,\psi_S]}{(pq)^{|S|}},\qquad
  E_S(f)=(pq)^{|S|}\hat f(S)^2\ \ge0 .
\]
In particular $\hat f(\emptyset)=\E_p[f]$.
\end{definition}

\begin{theorem}[Reproducing kernel]\label{thm:kernel}
For $0<p<1$ and all $\xi,\eta\in\cube$,
\[
  \sum_{S\subseteq\iota}\ \prod_{v\in S}\frac{\psi_v(\xi)\psi_v(\eta)}{pq}
  \;=\;\begin{cases}w_p(\eta)^{-1},&\xi=\eta,\\ 0,&\xi\neq\eta.\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
Put $a_v=\psi_v(\xi)\psi_v(\eta)/(pq)$. The subset-expansion identity
$\sum_{S\subseteq\iota}\prod_{v\in S}a_v=\prod_{v\in\iota}(1+a_v)$ reduces the claim
to inspecting one factor:
if $\xi_v\neq\eta_v$ then $\psi_v(\xi)\psi_v(\eta)=q\cdot(-p)$, so $a_v=-1$ and
$1+a_v=0$; if $\xi_v=\eta_v=1$ then $a_v=q/p$ and $1+a_v=1/p$; if
$\xi_v=\eta_v=0$ then $a_v=p/q$ and $1+a_v=1/q$. One disagreeing coordinate kills
the product, while total agreement gives $\prod_v(1/p\ \text{or}\ 1/q)=w_p(\eta)^{-1}$.
\end{proof}

\begin{theorem}[Completeness / Fourier inversion]\label{thm:complete}
For $0<p<1$, every $f:\cube\to\R$ satisfies $f=\sum_{S\subseteq\iota}\hat f(S)\psi_S$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $\hat f(S)\psi_S(\eta)=\sum_\xi w_p(\xi)f(\xi)\prod_{v\in S}\psi_v(\xi)\psi_v(\eta)/(pq)$
and exchange the two finite sums:
\[
  \sum_S\hat f(S)\psi_S(\eta)
  =\sum_\xi w_p(\xi)f(\xi)\sum_S\prod_{v\in S}\frac{\psi_v(\xi)\psi_v(\eta)}{pq}.
\]
By Theorem~\ref{thm:kernel} the inner sum is $\ind[\xi=\eta]\,w_p(\eta)^{-1}$, and
since $w_p(\eta)>0$ the double sum collapses to $f(\eta)$.
\end{proof}

\begin{remark}
The hypothesis $0<p<1$ is essential: at $p\in\{0,1\}$ the measure is a point mass,
$pq=0$, and most coefficients are undefined.
\end{remark}

\section{Parseval and the variance decomposition}

\begin{theorem}[Parseval]\label{thm:parseval}
For $0<p<1$ and all $f,g:\cube\to\R$,
\[
  \E_p[f\,g]=\sum_{S\subseteq\iota}(pq)^{|S|}\hat f(S)\hat g(S).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Insert $f=\sum_S\hat f(S)\psi_S$ (Theorem~\ref{thm:complete}) and use linearity:
$\E_p[fg]=\sum_S\hat f(S)\E_p[g\psi_S]=\sum_S\hat f(S)\hat g(S)(pq)^{|S|}$.
\end{proof}

\begin{theorem}[Variance form]\label{thm:variance}
For $0<p<1$, $\ \Var_p(f)=\sum_{S\neq\emptyset}E_S(f)$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $g=f$ in Theorem~\ref{thm:parseval} and split off the term $S=\emptyset$, equal
to $(\E_p[f])^2$.
\end{proof}

Variance is thus \emph{total nonconstant energy}, and $(E_S(f))_S$ is a complete
accounting of the randomness of $f$, sorted by frequency.

\section{Increasing events: the exact energy decomposition}

Throughout this section $A$ is increasing, $g=g_A$, $P=\PP_p(A)$,
$I_v=\PP_p(\Piv_v(A))$ and $E_S=E_S(g)$.

\begin{theorem}[Fourier form of Margulis--Russo]\label{thm:russo}
For every $v$, $\ \E_p[g\,\psi_v]=2pq\,I_v$; equivalently $\hat g(\{v\})=2I_v$ and
$E_{\{v\}}=4pq\,I_v^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Condition on the coordinates other than $v$. For an increasing event each
off-configuration falls into exactly one of three classes: the event holds
regardless of $v$; it fails regardless of $v$; or the off-configuration is pivotal.
In the first two classes $g$ does not depend on $v$ and the local contribution is
$g\cdot\E_p[\psi_v]=0$. In the third class $g=+1$ when $v$ is open and $-1$ when it
is closed, contributing $p\cdot q-q\cdot(-p)=2pq$ times the off-weight. Summing the
pivotal off-weights gives $2pq\,I_v$.
\end{proof}

Also $\hat g(\emptyset)=2P-1$, so $E_\emptyset=(2P-1)^2$.

\begin{theorem}[Biased Plancherel for Boolean functions]\label{thm:plancherel}
For $0<p<1$ and any event $A$, $\ \sum_{S\subseteq\iota}E_S=1$.
\end{theorem}

\begin{proof}[Proof sketch]
$g^2\equiv1$, so $\E_p[g^2]=1$; apply Theorem~\ref{thm:parseval} with $f=g$.
\end{proof}

The level energies of a Boolean function therefore form a probability distribution
over the $2^N$ frequencies: the \emph{spectral distribution} of the event.

\begin{theorem}[Exact energy decomposition]\label{thm:energy}
Let $A$ be increasing and $0<p<1$. Then
\[
  4P(1-P)\;=\;4pq\sum_{v\in\iota}I_v^2\;+\;R,
  \qquad R:=\sum_{|S|\ge2}E_S\ \ge\ 0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition the frequencies into $\emptyset$, the singletons and the sets of size
$\ge2$; by Theorem~\ref{thm:plancherel},
$1=(2P-1)^2+4pq\sum_vI_v^2+R$. Since $1-(2P-1)^2=4P(1-P)$, rearrange. Nonnegativity
of $R$ is termwise.
\end{proof}

\begin{corollary}[Equality case of \eqref{eq:l2}]\label{cor:l2eq}
If $\hat g(S)=0$ for all $|S|\ge2$, then $pq\sum_vI_v^2=P(1-P)$.
\end{corollary}

\begin{corollary}[Strict improvement]\label{cor:l2strict}
If $\hat g(S)\neq0$ for some $S$ with $|S|\ge2$, then $R>0$ and
$pq\sum_vI_v^2<P(1-P)$.
\end{corollary}

Thus \eqref{eq:l2} is \emph{nothing other than} the assertion $R\ge0$, and its slack
is exactly a quarter of the Fourier energy above degree one.

\begin{example}[Dictatorship]
$A=\{\eta_v=1\}$. Since $\psi_v=\eta_v-p$ we have $g=2\psi_v+(2p-1)$, so
$\hat g(\emptyset)=2p-1$, $\hat g(\{v\})=2$ and all other coefficients vanish. Here
$I_v=1$, $R=0$, and \eqref{eq:l2} is an equality: $pq=P(1-P)$.
\end{example}

\begin{example}[Majority of three at $p=1/2$]
In the $\pm1$ encoding $\mathrm{Maj}_3=\tfrac12(x_1+x_2+x_3-x_1x_2x_3)$. The energies
are $1/4$ at each of the three singletons and $1/4$ at $\{1,2,3\}$, totalling $1$.
With $P=1/2$ and $I_v=1/2$, Theorem~\ref{thm:energy} reads $1=\tfrac34+\tfrac14$;
the $\ell^2$ defect is $R/4=1/16$.
\end{example}

\section{The grid instance}

\begin{theorem}[Crossing energy decomposition]
Let $\mathrm{Cross}_n$ be the horizontal crossing event of the $n\times n$ grid at
$p=1/2$, with $P_n=\PP_{1/2}(\mathrm{Cross}_n)$. Then
\[
  4P_n(1-P_n)=\sum_{v}I_v^2+\sum_{|S|\ge2}E_S ,
\]
the sum running over the $n^2$ cells.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:energy} at $p=1/2$, where $4pq=1$, applied to the crossing event,
which is increasing.
\end{proof}

The interest is quantitative. The crossing event is nondegenerate, so the left-hand
side is of order $1$; by symmetry all $n^2$ cells have comparable influence, and the
square-root law forces $\sum_vI_v\le n$, whence
$\sum_vI_v^2\le\max_vI_v\cdot\sum_vI_v\to0$ as soon as the maximal influence tends
to $0$. Virtually all the spectral mass must therefore sit in $R$: the crossing event
has essentially no low-degree Fourier weight. This is the spectral signature of
\emph{noise sensitivity}.

\section{One-coordinate analysis and the site-energy identity}

We now allow arbitrary $f:\cube\to\R$.

\begin{lemma}[One-coordinate decomposition]\label{lem:decomp}
For every $v$ and $\eta$, $\ f(\eta)=A_vf(\eta)+\psi_v(\eta)\,D_vf(\eta)$.
\end{lemma}

\begin{proof}[Proof sketch]
If $\eta_v=1$ then $\eta^{v\to1}=\eta$ and $\psi_v(\eta)=q$, so the right-hand side
is $pf(\eta)+qf(\eta^{v\to0})+q(f(\eta)-f(\eta^{v\to0}))=f(\eta)$. If $\eta_v=0$ then
$\eta^{v\to0}=\eta$ and $\psi_v(\eta)=-p$, and the right-hand side is
$pf(\eta^{v\to1})+qf(\eta)-p(f(\eta^{v\to1})-f(\eta))=f(\eta)$.
\end{proof}

\begin{lemma}[One-coordinate integrals]\label{lem:integrals}
If $h$ is $v$-independent then $\E_p[\psi_v h]=0$ and
$\E_p[\psi_v^2 h]=pq\,\E_p[h]$.
\end{lemma}

\begin{proof}[Proof sketch]
Condition on the coordinates other than $v$: for each off-configuration $\zeta$ of
off-weight $\omega(\zeta)$ the two completions contribute
$\omega(\zeta)h(\zeta)(pq+q(-p))=0$ in the first case and
$\omega(\zeta)h(\zeta)(pq^2+qp^2)=pq\,\omega(\zeta)h(\zeta)$ in the second.
\end{proof}

A first consequence: a $v$-independent function has vanishing coefficients at every
$S\ni v$, since $\psi_S=\psi_v\psi_{S\setminus v}$ with $\psi_{S\setminus v}$
$v$-independent. A second, more useful one:

\begin{lemma}[Coefficients above a site are those of the derivative]\label{lem:erase}
For $0<p<1$, every $f$, every $v$ and every $S\ni v$,
$\ \hat f(S)=\widehat{D_vf}(S\setminus v)$.
\end{lemma}

\begin{proof}[Proof sketch]
Insert Lemma~\ref{lem:decomp} into $\E_p[f\psi_S]$ with $\psi_S=\psi_v\psi_{S\setminus v}$:
\[
  \E_p[f\psi_S]
  =\E_p\bigl[\psi_v\,(A_vf)\psi_{S\setminus v}\bigr]
   +\E_p\bigl[\psi_v^2\,(D_vf)\psi_{S\setminus v}\bigr].
\]
By Lemma~\ref{lem:integrals} the first term vanishes and the second equals
$pq\,\E_p[(D_vf)\psi_{S\setminus v}]$; divide by $(pq)^{|S|}=pq\,(pq)^{|S|-1}$.
\end{proof}

\begin{theorem}[Site energy identity]\label{thm:siteenergy}
For $0<p<1$, every $f$ and every $v$,
\[
  \sum_{S\ni v}E_S(f)\;=\;pq\;\E_p\bigl[(D_vf)^2\bigr].
\]
\end{theorem}

\begin{proof}[Proof sketch]
Reindex the sets containing $v$ by $T=S\setminus v$, so $|S|=|T|+1$. By
Lemma~\ref{lem:erase},
$\sum_{S\ni v}E_S(f)=pq\sum_{T\not\ni v}E_T(D_vf)$. Since $D_vf$ is $v$-independent,
its coefficients at sets containing $v$ vanish, so the restricted sum equals the full
sum $\sum_TE_T(D_vf)=\E_p[(D_vf)^2]$ by Theorem~\ref{thm:parseval}.
\end{proof}

This is the $p$-biased form of the classical identity
$\Inf_v(f)=\sum_{S\ni v}\hat f(S)^2$.

\begin{lemma}[Level multiplicity]\label{lem:mult}
$\displaystyle\sum_{v\in\iota}\sum_{S\ni v}E_S(f)=\sum_{S\subseteq\iota}|S|\,E_S(f)$.
\end{lemma}

\begin{proof}[Proof sketch]
Exchange the order of summation: each level $S$ appears once for every $v\in S$.
\end{proof}

\section{The exact Efron--Stein / Poincar\'e defect}

\begin{theorem}[Exact defect identity]\label{thm:defect}
For $0<p<1$ and every $f:\cube\to\R$,
\[
  pq\sum_{v\in\iota}\E_p\bigl[(D_vf)^2\bigr]-\Var_p(f)
  \;=\;\sum_{S\neq\emptyset}\bigl(|S|-1\bigr)E_S(f).
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:siteenergy} and Lemma~\ref{lem:mult} the first term equals
$\sum_S|S|E_S(f)$, in which $\emptyset$ contributes nothing; by
Theorem~\ref{thm:variance} the variance is $\sum_{S\neq\emptyset}E_S(f)$. Subtract
termwise over the nonempty levels.
\end{proof}

\begin{corollary}[Poincar\'e inequality]\label{cor:poincare}
Every term $(|S|-1)E_S(f)$ with $S\neq\emptyset$ is nonnegative, so
$\Var_p(f)\le pq\sum_v\E_p[(D_vf)^2]$.
\end{corollary}

The defect thus ignores the degree-one levels entirely --- these are the
Poincar\'e-extremal directions --- and overcounts each higher level exactly $|S|-1$
times.

\section{Specialization to increasing events}

\begin{lemma}[The derivative takes the values $0$ and $2$]\label{lem:derivsq}
For an increasing event, $(D_vg)^2=2\,D_vg$ pointwise.
\end{lemma}

\begin{proof}[Proof sketch]
Monotonicity forbids $\eta^{v\to0}\in A$ with $\eta^{v\to1}\notin A$, so
$D_vg(\eta)\in\{0,2\}$; and $t^2=2t$ on $\{0,2\}$.
\end{proof}

\begin{lemma}\label{lem:derivmean}
For $0<p<1$, $\ \E_p[D_vg]=2I_v$, hence $\E_p[(D_vg)^2]=4I_v$ and, by
Theorem~\ref{thm:siteenergy}, $\sum_{S\ni v}E_S=4pq\,I_v$.
\end{lemma}

\begin{proof}[Proof sketch]
$D_vg=2\,\ind_{\Piv_v(A)}$ pointwise by the trichotomy of Theorem~\ref{thm:russo};
take expectations. Alternatively, Lemmas~\ref{lem:decomp}--\ref{lem:integrals} give
$\E_p[g\psi_v]=pq\,\E_p[D_vg]$, which combined with Theorem~\ref{thm:russo} yields
the claim.
\end{proof}

\begin{theorem}[Total influence and the exact Poincar\'e defect]\label{thm:poindefect}
For $0<p<1$ and $A$ increasing,
\[
  4pq\sum_vI_v=\sum_S|S|\,E_S,
  \qquad
  4pq\sum_vI_v-4P(1-P)=\sum_{S\neq\emptyset}\bigl(|S|-1\bigr)E_S\ \ge\ 0 ,
\]
the second identity being \eqref{eq:poincare} with an exact remainder.
\end{theorem}

\begin{proof}[Proof sketch]
Combine Lemma~\ref{lem:derivmean} with Lemma~\ref{lem:mult}; then apply
Theorem~\ref{thm:defect} to $f=g$, using $\Var_p(g)=4P(1-P)$ and
$\E_p[(D_vg)^2]=4I_v$.
\end{proof}

\begin{theorem}[Equality case of the Poincar\'e inequality]\label{thm:poineq}
For $0<p<1$ and $A$ increasing,
\[
  P(1-P)=pq\sum_vI_v
  \iff
  \hat g(S)=0 \ \text{ for every } S \text{ with } |S|\ge2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) All terms with $|S|\ge2$ vanish by hypothesis, and those with $|S|=1$
carry the factor $|S|-1=0$. ($\Rightarrow$) A sum of nonnegative terms vanishes, so
each term vanishes; for $|S|\ge2$ the factor $|S|-1$ is positive, forcing $E_S=0$,
and $(pq)^{|S|}\neq0$ forces $\hat g(S)=0$.
\end{proof}

\begin{corollary}[Unified equality criterion]\label{cor:unified}
Let $A$ be increasing and $0<p<1$. The following are equivalent:
\begin{enumerate}
  \item $pq\sum_vI_v^2=P(1-P)$;
  \item $P(1-P)=pq\sum_vI_v$;
  \item $\hat g(S)=0$ for all $|S|\ge2$.
\end{enumerate}
\end{corollary}

\begin{proof}[Proof sketch]
(3)$\Rightarrow$(1) is Corollary~\ref{cor:l2eq}; (1)$\Rightarrow$(3) is
Corollary~\ref{cor:l2strict} in contrapositive; (2)$\Leftrightarrow$(3) is
Theorem~\ref{thm:poineq}.
\end{proof}

Two classical inequalities bounding $P(1-P)$ from opposite sides thus have
explicitly computable defects that are the \emph{same} level-energy ledger under two
weightings, and are tight simultaneously.

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Statement & Defect (in units of $\tfrac14$ of the total energy)\\
\midrule
$pq\sum_vI_v^2\le P(1-P)$ & $\displaystyle\sum_S\ind[|S|\ge2]\,E_S$\\[4pt]
$P(1-P)\le pq\sum_vI_v$   & $\displaystyle\sum_{S\neq\emptyset}(|S|-1)\,E_S$\\
\bottomrule
\end{tabular}
\end{center}

Since $\ind[k\ge2]\le k-1$ for every integer $k\ge1$, the Poincar\'e defect always
dominates the $\ell^2$ defect, with equality precisely when all energy above degree
one sits at degree exactly $2$.

\section{Algorithms}

All quantities are exactly computable in rational arithmetic when $p\in\mathbb{Q}$.

\subsection{Naive spectral computation}
Given $f$ as a table of $2^N$ values: precompute $w_p$ in $O(N2^N)$; then for each
of the $2^N$ frequencies evaluate
$\hat f(S)=(pq)^{-|S|}\sum_\eta w_p(\eta)f(\eta)\psi_S(\eta)$. Total: $O(N4^N)$.

\subsection{A division-free biased fast transform}
Lemma~\ref{lem:decomp} says that splitting a function at a coordinate $v$ into its
$v$-average and its $v$-derivative separates the frequencies omitting $v$ from those
containing $v$, and Lemma~\ref{lem:erase} identifies the latter with the coefficients
of $D_vf$. Iterating over the $N$ coordinates gives an $O(N2^N)$ butterfly:

\begin{quote}\ttfamily\small
BiasedFFT(f, p):\\
\hspace*{2em}q $\leftarrow$ 1 - p;\quad F $\leftarrow$ f\\
\hspace*{2em}for each coordinate v = 1..N:\\
\hspace*{4em}for each pair (F[$\eta^{v\to0}$], F[$\eta^{v\to1}$]):\\
\hspace*{6em}a $\leftarrow$ F[$\eta^{v\to0}$];\quad b $\leftarrow$ F[$\eta^{v\to1}$]\\
\hspace*{6em}F[$\eta^{v\to0}$] $\leftarrow$ p$\cdot$b + q$\cdot$a\qquad \# average: frequency omits v\\
\hspace*{6em}F[$\eta^{v\to1}$] $\leftarrow$ b - a\qquad\qquad\quad \# derivative: frequency contains v\\
\hspace*{2em}return F\qquad \# F[$\eta$], read with $\eta$ as the indicator of S, is $\hat f(S)$
\end{quote}

Remarkably the transform requires \emph{no division at all}: the normalizing factors
$(pq)^{|S|}$ built into the definition of $\hat f$ are cancelled exactly by the
recursion.

\subsection{Influences and defects}
From the spectrum and $E_S=(pq)^{|S|}\hat f(S)^2$: $\Var_p(f)=\sum_{S\neq\emptyset}E_S$;
$pq\,\E_p[(D_vf)^2]=\sum_{S\ni v}E_S$; for increasing events $I_v=\hat g(\{v\})/2$;
$\ell^2$ defect $=\tfrac14\sum_{|S|\ge2}E_S$; Poincar\'e defect
$=\tfrac14\sum_{S\neq\emptyset}(|S|-1)E_S$. Each is one pass over the frequencies.

\section{Numerical illustrations}

The following are exact rational values.

\medskip
\noindent\textbf{Dictatorship on one of three sites, $p=1/3$.}
$P=1/3$, $I_{v_1}=1$, other influences $0$. Spectrum: $\hat g(\emptyset)=-1/3$,
$\hat g(\{v_1\})=2$, all else $0$; energies $1/9$ and $8/9$, total $1$. Both defects
vanish: $pq\sum I_v^2=2/9=P(1-P)=pq\sum I_v$.

\medskip
\noindent\textbf{Majority of three, $p=1/2$.}
$P=1/2$, $I_v=1/2$. Energies: $1/4$ at each singleton and $1/4$ at the triple.
$\ell^2$: $3/16<1/4$, defect $1/16$. Poincar\'e: $3/8>1/4$, defect $1/8$.

\medskip
\noindent\textbf{AND of three, $p=1/2$.}
$P=1/8$, $I_v=1/4$, $P(1-P)=7/64$. $\ell^2$: $3/64<7/64$, defect $1/16$.
Poincar\'e: $12/64>7/64$, defect $5/64$.

\medskip
\noindent\textbf{$2\times2$ grid crossing, $p=1/2$.}
For the event ``at least one of the two rows is entirely open'' on cells
$a=(1,1),b=(1,2),c=(2,1),d=(2,2)$: $P=1-(3/4)^2=7/16$ and $P(1-P)=63/256$; each
cell has $I_v=3/8$. The level energies are $E_\emptyset=1/64$,
$E_{\{v\}}=9/64$ for each of the four singletons, $E_{\{a,b\}}=E_{\{c,d\}}=9/64$, and
$1/64$ for each of the remaining four pairs, the four triples and the full set;
these total $(1+36+18+4+4+1)/64=1$. The $\ell^2$ bound reads
$36/256\le63/256$ with defect $27/256$, and the Poincar\'e bound
$63/256\le96/256$ with defect $33/256$.

\medskip
\noindent\textbf{Majority of five, $p=1/2$.}
$P=1/2$, $I_v=3/8$. Spectral profile by degree: $45/64$ at degree $1$, $5/32$ at
degree $3$, $9/64$ at degree $5$ (all even degrees vanish by oddness). $\ell^2$
defect $19/256$; Poincar\'e defect $7/32$.

\medskip
In every case the total energy is exactly $1$, the energy decomposition of
Theorem~\ref{thm:energy} balances exactly, and the defect identity of
Theorem~\ref{thm:defect} holds for randomly generated non-Boolean functions as well.

\section{Discussion}

\subsection{What the identities buy}
\emph{Conceptual unification.} The $\ell^2$ influence bound and the Poincar\'e
inequality have entirely different classical proofs --- a Bessel/residual
computation on the incomplete family $\{1\}\cup\{\psi_v\}$, and a hybrid-path union
bound. Theorems~\ref{thm:energy} and \ref{thm:poindefect} show they are two
weightings of one nonnegative ledger.

\emph{Sharpness.} Corollary~\ref{cor:unified} gives a single checkable equality
criterion for both. Degree-$\le1$ Boolean functions on the biased cube appear to be
extremely rigid: exhaustive enumeration of all upward-closed events on $N\le4$ sites
(the Dedekind counts $3,6,20,168$) at $p=1/2$ and $p=1/3$, in exact rational
arithmetic, confirms the equivalence of the three conditions of
Corollary~\ref{cor:unified} in every case and finds that the only extremal events are
the two constants and the $N$ dictatorships. Every other monotone event on at most
four sites therefore has a strictly positive gap in \emph{both} inequalities
simultaneously. The same enumeration finds the largest attainable level-$\ge2$ energy
on four sites to be $27/64$, attained by the tribes event
$(x_1\wedge x_2)\vee(x_0\wedge x_3)$.

\emph{Quantitative improvement.} Any lower bound on the level-$\ge2$ energy upgrades
both inequalities: if a fraction $\rho$ of the spectral mass lies above degree one,
then $pq\sum_vI_v^2\le P(1-P)-\rho/4$ and $pq\sum_vI_v\ge P(1-P)+\rho/4$. This is
precisely the shape of estimate hypercontractive arguments supply.

\subsection{The role of the product rule}
Every result reduces to Theorem~\ref{thm:product}. This identifies the interface at
which the theory generalizes: any measure obeying a product rule --- in particular an
\emph{inhomogeneous} product measure with a distinct density $p_v$ at each site ---
supports the same development, with $\psi_v(\eta)=\eta_v-p_v$ and $(pq)^{|S|}$
replaced by $\prod_{v\in S}p_v(1-p_v)$. Every theorem above holds verbatim under
that replacement.

\subsection{Limitations}
The development is finite and algebraic. It does not by itself yield the KKL-type
conclusion that some influence is at least $c\log N/N$: that requires an estimate on
how spectral mass distributes across degrees, and no such estimate can follow from
orthogonality alone, which is degree-blind.

\section{Future directions}

\begin{conjecture}[Two-point hypercontractivity and its tensorization]
For every $f:\{0,1\}\to\R$, every $\rho\in[0,1]$ with
$\rho^2\le pq/\max(p,q)^2$, and the biased noise operator $T_\rho$, one has
$\|T_\rho f\|_4\le\|f\|_2$; and the same inequality holds for functions on
$\{0,1\}^{\iota}$ with the same $\rho$, by tensorizing along the product rule.
\end{conjecture}

The key insight is that the product rule is exactly the statement that the biased
measure is a product measure, and tensorization of a hypercontractive estimate is
repeated application of the product rule coordinate by coordinate; the two-point
case is a single two-variable polynomial inequality after clearing denominators.
Hypercontractivity is the only missing ingredient between the present development
and the whole KKL/Talagrand circle: with the Fourier expansion, Parseval, the level
decomposition and the site-energy identity in place, a hypercontractive estimate
immediately turns the remainder $R$ of Theorem~\ref{thm:energy} into a quantitative
statement, delivering the $\log N/N$ influence lower bound, Talagrand's
$\sum_vI_v/\log(1/I_v)$ bound, and Friedgut's junta theorem.

Further targets:
\begin{itemize}
  \item \emph{Noise stability and level-$k$ inequalities.} Define
        $\Stab_\rho(f)=\sum_S\rho^{|S|}E_S(f)$ and establish its semigroup properties
        directly from the product rule; then obtain the level-$k$ inequalities
        bounding the degree-$\le k$ energy of a small-measure event.
  \item \emph{Sharper defect estimates for geometric events.} Bound $R$ from below
        for crossing events on planar lattices, which would improve the square-root
        law for such events.
  \item \emph{Inhomogeneous densities.} Carry the development to a site-dependent
        density vector $(p_v)$ and combine with the site-dependent Margulis--Russo
        formula for directional threshold statements.
  \item \emph{Reverse defect bounds.} Identify the sharp constant replacing the
        trivial factor $N$ in the reverse Poincar\'e inequality, in terms of the
        spectral profile.
  \item \emph{Equality-case rigidity.} Classify all Boolean functions on the biased
        cube of Fourier degree at most one. Exhaustive enumeration for $N\le4$ finds
        only constants and dictatorships; a proof for all $N$ would turn
        Corollary~\ref{cor:unified} into a complete structural classification of the
        extremal events.
\end{itemize}

\section{Summary of the main results}

For a finite site set $\iota$, $0<p<1$, $q=1-p$, characters $\psi_v(\eta)=\eta_v-p$
and $\psi_S=\prod_{v\in S}\psi_v$, coefficients
$\hat f(S)=\E_p[f\psi_S]/(pq)^{|S|}$, and level energies
$E_S(f)=(pq)^{|S|}\hat f(S)^2$:

\begin{enumerate}
  \item \textbf{Product rule.} $\E_p[\prod_vg_v(\eta_v)]=\prod_v(pg_v(1)+qg_v(0))$.
  \item \textbf{Orthogonality.} $\E_p[\psi_S\psi_T]=\ind[S=T](pq)^{|S|}$.
  \item \textbf{Reproducing kernel.}
        $\sum_S\prod_{v\in S}\psi_v(\xi)\psi_v(\eta)/(pq)=\ind[\xi=\eta]/w_p(\eta)$.
  \item \textbf{Completeness.} $f=\sum_S\hat f(S)\psi_S$.
  \item \textbf{Parseval.} $\E_p[fg]=\sum_S(pq)^{|S|}\hat f(S)\hat g(S)$ and
        $\Var_p(f)=\sum_{S\neq\emptyset}E_S(f)$.
  \item \textbf{Plancherel for Boolean functions.} $\sum_SE_S(g_A)=1$.
  \item \textbf{Exact energy decomposition.}
        $4P(1-P)=4pq\sum_vI_v^2+\sum_{|S|\ge2}E_S$ for increasing $A$.
  \item \textbf{Site energy.} $\sum_{S\ni v}E_S(f)=pq\,\E_p[(D_vf)^2]$.
  \item \textbf{Exact Efron--Stein defect.}
        $pq\sum_v\E_p[(D_vf)^2]-\Var_p(f)=\sum_{S\neq\emptyset}(|S|-1)E_S(f)$.
  \item \textbf{Exact Poincar\'e defect and equality case.}
        $4pq\sum_vI_v-4P(1-P)=\sum_{S\neq\emptyset}(|S|-1)E_S$, with equality iff the
        event has degree at most one --- the same criterion as for the $\ell^2$
        bound.
\end{enumerate}

